<script setup lang="ts">
import type {Row} from '~/utils/resources'
interface Dashboard {now:string;kpis:Record<string,number>;statusCounts:Record<string,number>;series:{month:string;invoiced:number;collected:number}[];aging:{bucket:string;amount:number}[];mrrByPlan:{plan:string;mrr:number;count:number}[];topOverdue:{id:string;number:string;customer:string;amountDue:number;dueDate:string}[]}
const months=useState('reporting-months',()=>6),planId=useState('reporting-plan',()=>'')
const {data,status,error,refresh}=await useFetch<Dashboard>('/api/dashboard',{query:{months,planId}})
const {data:plans}=await useFetch<{items:Row[]}>('/api/plans')
const {data:billing}=await useFetch<{dueSubscriptions:number;draftInvoices:number;awaitingActivation:number;asOf:string}>('/api/billing/preview')
const {data:renewals}=await useFetch<{items:Row[]}>('/api/renewals',{query:{days:30}})
const {user}=useAuth(),api=useApi(),toast=useToast()
const busy=ref(false),simulation=useState('billing-simulation',()=>false),lastRun=useState<Row|null>('last-billing-run',()=>null)
const peak=computed(()=>Math.max(1,...(data.value?.series||[]).flatMap(s=>[s.invoiced,s.collected])))
const pipeline=['DRAFT','QUOTATION','CONFIRMED','ACTIVE','CLOSED']
const cards=[{key:'mrr',label:'Monthly recurring revenue',icon:'i-lucide-chart-no-axes-combined',cash:true,caption:'Normalised recurring value'},{key:'collectedThisMonth',label:'Collected this month',icon:'i-lucide-wallet',cash:true,caption:'Payments actually received'},{key:'outstanding',label:'Still to collect',icon:'i-lucide-circle-dollar-sign',cash:true,caption:'Confirmed invoices with a balance'},{key:'activeSubscriptions',label:'Active subscriptions',icon:'i-lucide-repeat',cash:false,caption:'Currently active contracts'}]
async function run(days?:number){busy.value=true;try{const before=data.value?.kpis.mrr;const result=await api<Row>(days?'/clock/advance':'/billing/run',{method:'POST',body:days?{days}:{}});lastRun.value={...(result.summary||result),days:days||0,at:new Date().toISOString(),beforeMrr:before};simulation.value=false;await refreshNuxtData();toast.add({title:days?'Billing month advanced':'Billing run complete',description:`${lastRun.value!.invoicesCreated||0} invoices created. Review the results below.`,color:'success'})}catch(e){toast.add({title:errorMessage(e),color:'error'})}finally{busy.value=false}}
async function renew(id:string){busy.value=true;try{await api(`/subscriptions/${id}/renew`,{method:'POST'});await refreshNuxtData();toast.add({title:'Contract renewed',color:'success'})}catch(e){toast.add({title:errorMessage(e),color:'error'})}finally{busy.value=false}}
</script>
<template><div class="page space-y-6">
<UAlert v-if="error" color="error" title="Could not load finance data" :description="errorMessage(error)"><template #actions><UButton @click="refresh()">Retry</UButton></template></UAlert>
<UPageGrid class="lg:grid-cols-4 gap-4 sm:gap-6 lg:gap-px"><UPageCard v-for="c in cards" :key="c.key" :icon="c.icon" :title="c.label" :to="c.key==='activeSubscriptions'?'/subscriptions?status=ACTIVE':c.key==='outstanding'?'/invoices?status=OUTSTANDING':c.key==='collectedThisMonth'?'/payments':'/subscriptions'" variant="subtle" :ui="{container:'gap-y-1.5',wrapper:'items-start',leading:'p-2.5 rounded-full bg-primary/10 ring ring-inset ring-primary/25 flex-col',title:'font-normal text-muted text-xs uppercase'}" class="lg:rounded-none first:rounded-l-lg last:rounded-r-lg hover:z-1"><USkeleton v-if="status==='pending'" class="h-8 w-28"/><span v-else class="text-2xl font-semibold text-highlighted tabular-nums">{{data?c.cash?money(data.kpis[c.key]):data.kpis[c.key]?.toLocaleString():'—'}}</span></UPageCard></UPageGrid>
<RevenueChart :series="data?.series||[]"/>
<div class="grid xl:grid-cols-3 gap-5"><UCard class="xl:col-span-2"><template #header><div class="flex justify-between gap-3"><div><h2 class="font-semibold">Today’s work queue</h2><p class="text-sm text-muted mt-1">Move the billing month forward.</p></div><UBadge variant="subtle" color="neutral">Operations</UBadge></div></template><div class="divide-y divide-default"><div class="flex items-center gap-4 py-4 first:pt-0"><span class="p-2.5 rounded-lg bg-primary/10 text-primary flex"><UIcon name="i-lucide-receipt" class="size-5"/></span><div class="flex-1"><p class="font-medium text-sm">Generate recurring invoices</p><p class="text-xs text-muted mt-1">{{billing?.dueSubscriptions??'—'}} active contracts due · {{billing?.awaitingActivation??0}} ready to activate</p></div><UButton :loading="busy" @click="run()">Run billing</UButton></div><NuxtLink to="/invoices?status=OVERDUE" class="flex items-center gap-4 py-4 group"><span class="p-2.5 rounded-lg bg-warning/10 text-warning flex"><UIcon name="i-lucide-alarm-clock" class="size-5"/></span><div class="flex-1"><p class="font-medium text-sm">Recover overdue revenue</p><p class="text-xs text-muted mt-1">{{data?.kpis.overdueCount??'—'}} invoices · {{money(data?.kpis.overdue)}} outstanding</p></div><UIcon name="i-lucide-arrow-right" class="text-muted group-hover:text-primary"/></NuxtLink><NuxtLink to="/reconcile" class="flex items-center gap-4 py-4 group"><span class="p-2.5 rounded-lg bg-elevated text-muted flex"><UIcon name="i-lucide-git-compare-arrows" class="size-5"/></span><div class="flex-1"><p class="font-medium text-sm">Match bank payments</p><p class="text-xs text-muted mt-1">Upload a statement, review matches, record payments.</p></div><UIcon name="i-lucide-arrow-right" class="text-muted group-hover:text-primary"/></NuxtLink><NuxtLink to="/invoices?status=DRAFT" class="flex items-center gap-4 py-4 pb-0 group"><span class="p-2.5 rounded-lg bg-elevated text-muted flex"><UIcon name="i-lucide-file-check-2" class="size-5"/></span><div class="flex-1"><p class="font-medium text-sm">Review draft invoices</p><p class="text-xs text-muted mt-1">{{billing?.draftInvoices??'—'}} awaiting confirmation</p></div><UIcon name="i-lucide-arrow-right" class="text-muted group-hover:text-primary"/></NuxtLink></div></UCard>
<UCard><template #header><h2 class="font-semibold">Subscription lifecycle</h2><p class="text-sm text-muted mt-1">From the first quote to the final invoice.</p></template><NuxtLink v-for="(stage,i) in pipeline" :key="stage" :to="`/subscriptions?status=${stage}`" class="flex items-center gap-3 py-2.5"><span class="size-7 flex items-center justify-center rounded-full text-xs font-medium" :class="stage==='ACTIVE'?'bg-primary/10 text-primary':'bg-elevated text-muted'">{{i+1}}</span><span class="flex-1 text-sm capitalize">{{stage.toLowerCase()}}</span><span class="font-medium tabular-nums">{{(data?.statusCounts?.[stage]||0).toLocaleString()}}</span></NuxtLink><UButton to="/templates" variant="link" class="px-0 mt-3" trailing-icon="i-lucide-arrow-right">Start from a quotation template</UButton></UCard></div>
<UAlert v-if="lastRun" color="success" variant="subtle" icon="i-lucide-circle-check" :title="lastRun.days?`Advanced ${lastRun.days} days · billing processed`:'Billing run complete'"><template #description><div class="flex flex-wrap gap-x-6 gap-y-2 mt-2 text-sm"><span><strong>{{lastRun.invoicesCreated||0}}</strong> invoices created</span><span><strong>{{lastRun.duplicatesBlocked||0}}</strong> duplicates blocked</span><span><strong>{{lastRun.renewed||0}}</strong> renewals</span><span><strong>{{lastRun.closed||0}}</strong> closed contracts</span><span><strong>{{lastRun.quotesExpired||0}}</strong> expired quotes</span></div></template></UAlert>
<div><UCard><template #header><h2 class="font-semibold">Revenue by plan</h2><p class="text-xs text-muted mt-1">Monthly recurring revenue from active contracts.</p></template><div class="space-y-5"><div v-for="plan in data?.mrrByPlan" :key="plan.plan"><div class="flex justify-between gap-3 text-sm mb-2"><span class="truncate">{{plan.plan}}</span><span class="font-medium whitespace-nowrap">{{money(plan.mrr)}}</span></div><UProgress :model-value="plan.mrr" :max="Math.max(1,data?.kpis.mrr||1)" size="xs"/><p class="text-xs text-dimmed mt-1">{{plan.count.toLocaleString()}} subscriptions</p></div><p v-if="!data?.mrrByPlan.length" class="text-sm text-muted">Active plan revenue will appear here.</p></div></UCard></div>
<div class="grid xl:grid-cols-2 gap-5"><UCard><template #header><div class="flex justify-between items-center"><div><h2 class="font-semibold">Renewals on the radar</h2><p class="text-xs text-muted mt-1">Contracts expiring within 30 days, oldest first.</p></div><UButton to="/renewals" color="neutral" variant="ghost" size="xs" trailing-icon="i-lucide-arrow-right">View all</UButton></div></template><div v-for="s in renewals?.items.slice(0,5)" :key="s.id" class="flex gap-3 items-center border-b border-default py-3 first:pt-0 last:border-0"><div class="flex-1 min-w-0"><NuxtLink :to="`/subscriptions/${s.id}`" class="font-medium text-sm hover:text-primary">{{s.customer.name}}</NuxtLink><p class="text-xs text-muted mt-1 truncate">{{s.plan.name}} · {{date(s.expiryDate)}}</p></div><UBadge v-if="s.autoRenew" variant="subtle" color="neutral" size="xs">Auto renew</UBadge><UButton v-else-if="s.plan.renewable" variant="soft" size="xs" :loading="busy" @click="renew(s.id)">Renew</UButton><UButton v-else :to="`/subscriptions/${s.id}`" color="neutral" variant="ghost" size="xs">Review</UButton></div><p v-if="!renewals?.items.length" class="text-muted text-sm py-6">No upcoming renewals to review.</p></UCard><UCard><template #header><div class="flex justify-between items-center"><div><h2 class="font-semibold">Oldest overdue invoices</h2><p class="text-xs text-muted mt-1">Prioritise the balances that have waited longest.</p></div><UButton to="/invoices?status=OVERDUE" color="neutral" variant="ghost" size="xs" trailing-icon="i-lucide-arrow-right">View all</UButton></div></template><NuxtLink v-for="inv in data?.topOverdue.slice(0,5)" :key="inv.id" :to="`/invoices/${inv.id}`" class="flex justify-between gap-3 border-b border-default py-3 first:pt-0 last:border-0"><div class="min-w-0"><p class="text-sm font-medium truncate">{{inv.customer}}</p><p class="text-xs text-muted mt-1">{{inv.number}} · {{date(inv.dueDate)}}</p></div><span class="text-sm font-medium whitespace-nowrap">{{money(inv.amountDue)}}</span></NuxtLink><p v-if="!data?.topOverdue.length" class="text-sm text-muted py-6">No overdue balances. You’re up to date.</p></UCard></div>
<UModal v-model:open="simulation" title="Rehearse a billing month" description="Advance the demo clock to see billing rules run on real subscription data."><template #body><div class="space-y-5"><UAlert color="warning" variant="subtle" title="This changes demo data" description="Advancing time creates real invoices and processes renewals, expiry rules and quotation deadlines. Resetting the clock does not undo these records."/><div class="grid grid-cols-3 gap-3"><UButton :loading="busy" variant="outline" block @click="run(1)">+1 day</UButton><UButton :loading="busy" variant="outline" block @click="run(7)">+1 week</UButton><UButton :loading="busy" block @click="run(30)">+30 days</UButton></div><p class="text-sm text-muted">After the run, review invoice creation, automatic renewals and expired quotes in the result panel. Run billing again to demonstrate that no period is billed twice.</p></div></template></UModal>
</div></template>
